import { BEV_ICONS } from './bevIcons.generated';

/**
 * Authored beverage icons, keyed by catalog bevId. The map and the SVGs in `app/public/bev-icons/`
 * are generated by `node scripts/icons/export-app.mjs` from `design/beverage-icons/manifest.json`;
 * never edit them by hand. An icon is art, not a photo: a Bev's image is photo > icon > category
 * art (`bevImageProps` in `@/components/BevParts`).
 */
export function bevIconUri(bevId: string): string | undefined {
  return Object.prototype.hasOwnProperty.call(BEV_ICONS, bevId) ? BEV_ICONS[bevId] : undefined;
}

/** True when the Bev has an authored icon. */
export function hasBevIcon(bevId: string): boolean {
  return bevIconUri(bevId) !== undefined;
}
